<script setup>defineProps({label:{type:String,default:'正在加载…'},block:Boolean})</script><template><span class="loading" :class="{block}" role="status"><i/>{{label}}</span></template><style scoped>.loading{display:inline-flex;align-items:center;gap:8px;color:var(--muted);font-size:11px}.block{display:flex;justify-content:center;padding:24px}i{width:15px;height:15px;border:2px solid var(--line);border-top-color:var(--primary);border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}</style>